    "body_length": 0.1,
    "body_width": 0.12,
    "mass": 0.6,
    "sensor_positions": [
      {"x": -0.03, "y": 0.075},
      {"x": -0.015, "y": 0.075},
      {"x": 0.0, "y": 0.075},
      {"x": 0.015, "y": 0.075},
      {"x": 0.03, "y": 0.075}
